# Application-level conflict resolution for multi-leader writes
def resolve_conflict(version_a, version_b):
    """Merge two concurrent writes by taking field-level last-write-wins."""
    resolved = {}
    all_keys = set(version_a['data'].keys()) | set(version_b['data'].keys())
    for key in all_keys:
        a = version_a['data'].get(key)
        b = version_b['data'].get(key)
        # Pick the version with the higher timestamp for each field
        if a is None:
            resolved[key] = b
        elif b is None:
            resolved[key] = a
        elif version_a['timestamp'] >= version_b['timestamp']:
            resolved[key] = a
        else:
            resolved[key] = b
    return resolved

import random
import boto3

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table('Events')

NUM_SALTS = 20

def write_event(user_id: str, event: dict):
    salt = random.randint(0, NUM_SALTS - 1)
    table.put_item(Item={
        'pk': f'{user_id}#{salt}',  # salted partition key
        'sk': event['timestamp'],
        **event
    })

def read_all_events(user_id: str):
    all_items = []
    for salt in range(NUM_SALTS):
        resp = table.query(
            KeyConditionExpression='pk = :pk',
            ExpressionAttributeValues={':pk': f'{user_id}#{salt}'}
        )
        all_items.extend(resp['Items'])
    return sorted(all_items, key=lambda x: x['sk'])

