-- Demonstrating non-repeatable read under Read Committed
BEGIN; -- isolation level READ COMMITTED (PG default)

SELECT balance FROM accounts WHERE id = 42;
-- Returns: 1000

-- Another session commits: UPDATE accounts SET balance = 800 WHERE id = 42

SELECT balance FROM accounts WHERE id = 42;
-- Returns: 800  ← different value! non-repeatable read

ROLLBACK;

-- Fix: upgrade to REPEATABLE READ
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT balance FROM accounts WHERE id = 42;  -- 1000
-- (concurrent update commits)
SELECT balance FROM accounts WHERE id = 42;  -- still 1000

-- UNSAFE: read-modify-write creates lost update window
BEGIN;
SELECT balance FROM accounts WHERE id = 42;  -- reads 100
-- concurrent transaction ALSO reads 100
UPDATE accounts SET balance = 110 WHERE id = 42;  -- writes 110
COMMIT;
-- Other transaction writes 115, overwriting 110 → lost update

-- SAFE option 1: atomic in-place increment
UPDATE accounts SET balance = balance + 10 WHERE id = 42;

-- SAFE option 2: pessimistic SELECT FOR UPDATE
BEGIN;
SELECT balance FROM accounts WHERE id = 42 FOR UPDATE;  -- blocks other writers
UPDATE accounts SET balance = balance + 10 WHERE id = 42;
COMMIT;

-- Write skew example: on-call invariant
-- Transaction A: Alice checks at least 2 on-call, decides to go off
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM on_call WHERE status = 'active';  -- returns 2
UPDATE on_call SET status = 'off' WHERE doctor = 'alice';
COMMIT;

-- Concurrent Transaction B: Bob does the same
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM on_call WHERE status = 'active';  -- also returns 2
UPDATE on_call SET status = 'off' WHERE doctor = 'bob';
COMMIT;  -- succeeds! now 0 doctors on call

-- Fix: use SERIALIZABLE isolation
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
-- SSI will detect the rw-conflict and abort one transaction

-- Phantom read scenario under READ COMMITTED
BEGIN; -- isolation: READ COMMITTED

SELECT count(*) FROM orders WHERE status = 'pending';
-- Returns: 42

-- Concurrent transaction inserts 3 new 'pending' orders and commits

SELECT count(*) FROM orders WHERE status = 'pending';
-- Returns: 45  ← phantom rows appeared!

ROLLBACK;

-- Prevented under REPEATABLE READ (MVCC snapshot):
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM orders WHERE status = 'pending';
-- Returns: 42
-- (concurrent inserts commit)
SELECT count(*) FROM orders WHERE status = 'pending';
-- Returns: 42  ← snapshot prevents phantoms

# Fencing token enforcement in a storage server
class FencedStorage:
    def __init__(self):
        self._data = {}
        self._max_token = {}  # highest seen token per key

    def write(self, key: str, value, fencing_token: int) -> bool:
        current_max = self._max_token.get(key, 0)
        if fencing_token < current_max:
            # Stale lock holder — reject
            raise StaleTokenError(
                f'Token {fencing_token} rejected; current max is {current_max}'
            )
        self._max_token[key] = fencing_token
        self._data[key] = value
        return True

    def read(self, key: str):
        return self._data.get(key)

import hashlib
import bisect

class ConsistentHashRing:
    def __init__(self, nodes, virtual_nodes=150):
        self.ring = {}
        self.sorted_keys = []
        for node in nodes:
            for i in range(virtual_nodes):
                key = int(hashlib.md5(f'{node}#{i}'.encode()).hexdigest(), 16)
                self.ring[key] = node
                bisect.insort(self.sorted_keys, key)

    def get_node(self, key: str) -> str:
        h = int(hashlib.md5(key.encode()).hexdigest(), 16)
        idx = bisect.bisect(self.sorted_keys, h) % len(self.sorted_keys)
        return self.ring[self.sorted_keys[idx]]

ring = ConsistentHashRing(['node-1', 'node-2', 'node-3'])
print(ring.get_node('user:42'))  # consistently maps to the same node

import concurrent.futures

def scatter_gather_query(query, partitions):
    """Fan out a query to all partitions and merge results."""
    def query_partition(partition):
        return partition.search(query)

    # Scatter: fan out in parallel
    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = {
            executor.submit(query_partition, p): p
            for p in partitions
        }

    # Gather: collect and merge results
    all_results = []
    for future in concurrent.futures.as_completed(futures):
        all_results.extend(future.result())

    # Merge: sort by relevance score, return top-K
    return sorted(all_results, key=lambda r: r.score, reverse=True)[:10]

